import React, { useEffect, useMemo, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, TextInput, View, SafeAreaView } from 'react-native';
import { Svg, Circle, Path, Rect } from '../src/Svg';
import { Ionicons, type IconName } from '../src/Ionicons';

type Mood = 'Relax' | 'Clear my mind' | 'Recharge' | 'Explore' | 'Lift my mood' | 'Get active';
type Tab = 'Discover' | 'Explore' | 'Saved' | 'Profile';
type Screen = 'welcome' | 'home' | 'moods' | 'preferences' | 'priorities' | 'results' | 'detail' | 'music' | 'walking' | 'complete' | 'feedback';
type Route = { id: string; name: string; area: string; minutes: number; km: number; difficulty: 'Easy' | 'Moderate'; tags: string[]; moods: Mood[]; description: string; green: number; noise: number; crowd: number; safety: number; lighting: string; color: string };
type Review = { routeId: string; mood: Mood; feeling: string; date: string };
type Walk = { routeId: string; minutes: number; km: number; date: string; mood: Mood };
type Store = { saved: string[]; reviews: Review[]; walks: Walk[]; onboarded: boolean };

const C = { bg: '#F7F8F4', ink: '#29352E', muted: '#748078', green: '#527A61', dark: '#345744', sage: '#E8EFE8', white: '#FFFFFF', line: '#E3E8E1', sand: '#F1EBDD', orange: '#E8A66A', pale: '#F3F5EF' };
const KEY = 'moodwalk.v1';
const moods: { label: Mood; icon: IconName; hint: string; color: string }[] = [
  { label: 'Relax', icon: 'leaf-outline', hint: 'Slow down and unwind', color: '#E6EFE5' },
  { label: 'Clear my mind', icon: 'cloud-outline', hint: 'Make space to think', color: '#E8EEF0' },
  { label: 'Recharge', icon: 'sunny-outline', hint: 'Get a fresh start', color: '#F7EBD9' },
  { label: 'Explore', icon: 'compass-outline', hint: 'Find a new place', color: '#EEE8F2' },
  { label: 'Lift my mood', icon: 'happy-outline', hint: 'Change the scenery', color: '#F5E8E2' },
  { label: 'Get active', icon: 'walk-outline', hint: 'Move a little more', color: '#F0EBDD' },
];
const musicIdeas: Record<Mood, string[]> = {
  Relax: ['Soft acoustic', 'Quiet piano', 'Ambient outdoors'],
  'Clear my mind': ['Lo-fi instrumentals', 'Slow piano', 'Gentle ambient'],
  Recharge: ['Warm acoustic', 'Bright indie', 'Light electronic'],
  Explore: ['Indie discoveries', 'City pop', 'World instrumentals'],
  'Lift my mood': ['Sunny indie pop', 'Feel-good acoustic', 'Upbeat lo-fi'],
  'Get active': ['Upbeat indie', 'Steady beats', 'Feel-good pop'],
};
const timeOptions = ['15–30 min', '30–60 min', 'Flexible'];
const environments = ['Green spaces', 'Quiet streets', 'Well-lit & safe', 'Shortest walk', 'Lively streets', 'Surprise me'];
const routeData: Route[] = [
  { id: 'park', name: 'Peaceful Park Escape', area: 'Seoul Forest · Seongdong-gu', minutes: 22, km: 1.4, difficulty: 'Easy', tags: ['Green', 'Quiet', 'Well lit', 'Flat path'], moods: ['Relax', 'Clear my mind', 'Recharge', 'Lift my mood'], description: 'A gentle loop beneath the trees, with wide paths and quieter corners to slow down and reset.', green: 5, noise: 1, crowd: 2, safety: 4, lighting: 'Main paths are illustrated as lit', color: '#BBD2B6' },
  { id: 'river', name: 'Riverside Reset', area: 'Ttukseom Hangang Park', minutes: 31, km: 2.1, difficulty: 'Easy', tags: ['Open views', 'Water', 'Quiet', 'Well lit'], moods: ['Clear my mind', 'Relax', 'Lift my mood'], description: 'Follow the open riverside path for expansive views and room to let your thoughts settle.', green: 4, noise: 2, crowd: 2, safety: 4, lighting: 'Open riverside path (sample)', color: '#B9D6D8' },
  { id: 'lanes', name: 'Little Streets, New Finds', area: 'Seongsu-dong', minutes: 26, km: 1.8, difficulty: 'Easy', tags: ['Cafes', 'Discover', 'Local', 'Well lit'], moods: ['Explore', 'Recharge', 'Get active', 'Lift my mood'], description: 'A friendly wander past independent cafes, converted workshops, and small neighborhood details.', green: 2, noise: 3, crowd: 3, safety: 4, lighting: 'Busier streets (sample)', color: '#E6C9AA' },
  { id: 'campus', name: 'Campus Garden Loop', area: 'University campus · Seoul', minutes: 18, km: 1.1, difficulty: 'Easy', tags: ['Short', 'Green', 'Accessible', 'Well lit'], moods: ['Recharge', 'Relax', 'Lift my mood'], description: 'A compact, low-effort loop with benches and garden paths close to campus buildings.', green: 4, noise: 2, crowd: 2, safety: 4, lighting: 'Campus paths (sample)', color: '#C6D8BD' },
  { id: 'hill', name: 'Sunlit Hill Lookout', area: 'Namsan lower trail', minutes: 43, km: 2.7, difficulty: 'Moderate', tags: ['Views', 'Brisk', 'Green'], moods: ['Get active', 'Lift my mood', 'Explore'], description: 'A steady climb through leafy paths opens onto a rewarding view across the city.', green: 4, noise: 2, crowd: 3, safety: 3, lighting: 'Trail lighting varies (sample)', color: '#D6C99B' },
  { id: 'stream', name: 'Cheonggyecheon Stroll', area: 'Jongno · downtown Seoul', minutes: 29, km: 2.0, difficulty: 'Easy', tags: ['Water', 'City', 'Mostly flat', 'Well lit'], moods: ['Clear my mind', 'Explore', 'Get active'], description: 'A mostly flat waterside route that gives a refreshing pocket of calm in the city.', green: 3, noise: 2, crowd: 3, safety: 4, lighting: 'Central path (sample)', color: '#B5D8D2' },
];

const blankStore: Store = { saved: [], reviews: [], walks: [], onboarded: false };
const durationRange = (choice: string) => choice === '15–30 min' ? [15, 30] : choice === '30–60 min' ? [30, 60] : [0, 999];
const moodIcon = (mood: Mood) => moods.find(m => m.label === mood)?.icon ?? 'leaf-outline';

export default function MoodWalk() {
  const [store, setStore] = useState<Store>(blankStore);
  const [ready, setReady] = useState(false);
  const [screen, setScreen] = useState<Screen>('welcome');
  const [tab, setTab] = useState<Tab>('Discover');
  const [mood, setMood] = useState<Mood>('Relax');
  const [time, setTime] = useState('15–30 min');
  const [environment, setEnvironment] = useState<string[]>(['Green spaces', 'Well-lit & safe']);
  const [route, setRoute] = useState<Route>(routeData[0]);
  const [selectedMusic, setSelectedMusic] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [paused, setPaused] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [locationLabel, setLocationLabel] = useState('Seoul, South Korea');

  useEffect(() => { try { const value = window.localStorage.getItem(KEY); if (value) { const parsed = JSON.parse(value) as Store; setStore({ ...blankStore, ...parsed }); setScreen(parsed.onboarded ? 'home' : 'welcome'); } } catch { /* Storage may be unavailable in private browsing. */ } finally { setReady(true); } }, []);
  useEffect(() => { if (ready) { try { window.localStorage.setItem(KEY, JSON.stringify(store)); } catch { /* Keep the session usable when storage is full or blocked. */ } } }, [ready, store]);
  useEffect(() => { if (screen !== 'walking' || paused) return; const timer = setInterval(() => setElapsed(s => s + 1), 1000); return () => clearInterval(timer); }, [screen, paused]);

  const recommendations = useMemo(() => {
    const [min, max] = durationRange(time);
    return [...routeData].map(r => {
      let score = r.moods.includes(mood) ? 5 : 0;
      const prefs = [
        ['Green spaces', ['Green']], ['Quiet streets', ['Quiet']], ['Well-lit & safe', ['Well lit']],
        ['Shortest walk', ['Short', 'Mostly flat']], ['Lively streets', ['Cafes', 'Local']], ['Surprise me', ['Discover', 'Open views', 'Water']]
      ] as const;
      for (const pref of environment) { const match = prefs.find(p => p[0] === pref); if (match && match[1].some(t => r.tags.includes(t))) score += 2; }
      if (r.minutes >= min && r.minutes <= max) score += 3;
      else if (min > 0) score -= 1;
      if (environment.includes('Shortest walk')) score += Math.max(0, 4 - Math.floor(r.minutes / 12));
      const recentReviews = store.reviews.filter(review => review.routeId === r.id).slice(0, 3);
      for (const review of recentReviews) {
        if (review.feeling === 'Much better' || review.feeling === 'A little better') score += 1;
        if (review.feeling === 'More stressed' || review.feeling === 'More tired') score -= 2;
      }
      return { route: r, score };
    }).sort((a, b) => b.score - a.score).slice(0, 3).map(x => x.route);
  }, [mood, time, environment, store.reviews]);

  const routeWhy = (r: Route) => {
    const moodFit = r.moods.includes(mood) ? `A good fit for “${mood.toLowerCase()}”` : 'A fresh option to explore';
    const envFit = environment.find(e => (e === 'Green spaces' && r.tags.includes('Green')) || (e === 'Quiet streets' && r.tags.includes('Quiet')) || (e === 'Well-lit & safe' && r.tags.includes('Well lit')) || (e === 'Shortest walk' && r.tags.includes('Short')) || (e === 'Lively streets' && r.tags.includes('Cafes')) || (e === 'Surprise me' && r.tags.includes('Discover')));
    return envFit ? `${moodFit}, with ${envFit.toLowerCase()} along the way.` : `${moodFit}, at a ${r.minutes}-minute walking pace.`;
  };
  const toggleEnvironment = (choice: string) => {
    if (environment.includes(choice)) { setEnvironment(current => current.filter(x => x !== choice)); return; }
    if (choice === 'Surprise me') { setEnvironment(['Surprise me']); return; }
    if (environment.includes('Surprise me')) { setEnvironment([choice]); return; }
    if (environment.length >= 2) { window.alert('Pick up to two: choose the two route details that matter most today.'); return; }
    setEnvironment(current => [...current, choice]);
  };
  const toggleSaved = (id: string) => {
    if (store.saved.includes(id)) {
      if (window.confirm('Remove saved route? You can always save it again later.')) setStore(current => ({ ...current, saved: current.saved.filter(x => x !== id) }));
    } else setStore(current => ({ ...current, saved: [...current.saved, id] }));
  };
  const openRoute = (r: Route) => { setRoute(r); setSelectedMusic(null); setScreen('detail'); };
  const startWalk = () => { setElapsed(0); setPaused(false); setScreen('walking'); };
  const finishWalk = () => { setStore(s => ({ ...s, walks: [{ routeId: route.id, minutes: Math.max(1, Math.round(elapsed / 60) || route.minutes), km: route.km, date: new Date().toISOString(), mood }, ...s.walks] })); setScreen('complete'); };
  const submitFeedback = (feeling: string) => {
    const review: Review = { routeId: route.id, mood, feeling, date: new Date().toISOString() };
    setStore(current => ({ ...current, reviews: [review, ...current.reviews] }));
    setScreen('home'); setTab('Discover');
    window.alert('Saved, thank you. Your one-tap check-in is saved on this device.');
  };
  const findLocation = async () => { if (!navigator.geolocation) { window.alert('Location is unavailable in this browser. Sample routes are ready to explore.'); return; } navigator.geolocation.getCurrentPosition(position => setLocationLabel(`${position.coords.latitude.toFixed(2)}°, ${position.coords.longitude.toFixed(2)}°`), () => window.alert('Location access is off or unavailable. Sample routes are ready to explore.'), { enableHighAccuracy: false, timeout: 10000 }); };

  const goTab = (next: Tab) => { setTab(next); setScreen('home'); };
  const begin = () => { setStore(s => ({ ...s, onboarded: true })); setScreen('home'); };

  if (!ready) return <SafeAreaView style={s.safe}><View style={s.loading}><View style={s.logoMark}><Ionicons name="leaf" size={24} color={C.white} /></View></View></SafeAreaView>;

  if (screen === 'welcome') return <SafeAreaView dataSet={{ mobile: 'app-safe-area' }} style={s.safe}><View dataSet={{ mobile: 'welcome-screen' }} style={s.welcome}>
    <View style={s.brand}><View style={s.logoMark}><Ionicons name="leaf" size={23} color={C.white} /></View><Text style={s.brandText}>moodwalk</Text></View>
    <View dataSet={{ mobile: 'welcome-art' }} style={s.welcomeArt}><ScenicArt /><View style={s.artPill}><Ionicons name="sparkles" size={15} color={C.dark} /><Text style={s.artPillText}>A little space for you</Text></View></View>
    <View dataSet={{ mobile: 'welcome-copy' }} style={s.welcomeCopy}><Text style={s.eyebrow}>YOUR NEXT BREATH OF FRESH AIR</Text><Text style={s.hero}>A walk that{ '\n' }fits how you feel.</Text><Text style={s.body}>Tell us what you need today. We’ll find a nearby route that feels right for you.</Text>
      <Button label="Find my kind of walk" icon="arrow-forward" onPress={begin} />
    </View>
  </View></SafeAreaView>;

  const header = (title: string, subtitle?: string, back?: () => void) => <View style={s.pageHeader}>
    {back ? <Pressable onPress={back} accessibilityRole="button" accessibilityLabel="Go back" style={s.backButton}><Ionicons name="chevron-back" size={22} color={C.ink} /></Pressable> : null}
    <View style={{ flex: 1 }}><Text style={s.pageTitle}>{title}</Text></View>
  </View>;

  const routeCard = (r: Route, compact = false) => <Pressable key={r.id} style={[s.routeCard, compact && s.routeCardCompact]} onPress={() => openRoute(r)} accessibilityRole="button" accessibilityLabel={`Open ${r.name}, ${r.minutes} minutes, ${r.km} kilometers`}>
    <View style={s.routeImage}><MiniMap color={r.color} /><Pressable onPress={e => { e.stopPropagation(); toggleSaved(r.id); }} style={s.bookmark} accessibilityRole="button" accessibilityLabel={store.saved.includes(r.id) ? 'Remove saved route' : 'Save route'}><Ionicons name={store.saved.includes(r.id) ? 'bookmark' : 'bookmark-outline'} size={18} color={store.saved.includes(r.id) ? C.green : C.ink} /><Text style={s.bookmarkText}>{store.saved.includes(r.id) ? 'Saved' : 'Save'}</Text></Pressable><View style={s.mapBadge}><Ionicons name="navigate" size={12} color={C.dark} /><Text style={s.mapBadgeText}>SAMPLE DATA</Text></View></View>
    <View style={s.routeInfo}><View style={s.routeTitleRow}><View style={{ flex: 1 }}><Text style={s.routeName}>{r.name}</Text><Text style={s.routeArea}>{r.area}</Text></View><Ionicons name="arrow-forward" size={19} color={C.muted} /></View>
      <View style={s.metrics}><Metric icon="time-outline" label={`${r.minutes} min`} /><Metric icon="walk-outline" label={`${r.km.toFixed(1)} km`} /><Metric icon="shield-checkmark-outline" label={`Sample safety ${r.safety}/5`} /></View>
      <Text style={s.why}>{routeWhy(r)}</Text><View style={s.tagRow}>{r.tags.slice(0, 3).map(t => <Tag key={t} label={t} />)}</View>
    </View>
  </Pressable>;

  const nav = <View dataSet={{ mobile: 'mobile-tabbar' }} style={s.tabBar}>{(['Discover', 'Explore', 'Saved', 'Profile'] as Tab[]).map(t => <Pressable key={t} onPress={() => goTab(t)} style={s.tabItem} accessibilityRole="tab" accessibilityState={{ selected: tab === t }}><Ionicons name={(t === 'Discover' ? 'leaf' : t === 'Explore' ? 'compass' : t === 'Saved' ? 'bookmark' : 'person-circle') as IconName} size={21} color={tab === t ? C.green : '#929A94'} /><Text style={[s.tabLabel, tab === t && s.tabLabelActive]}>{t}</Text>{tab === t && <View style={s.tabDot} />}</Pressable>)}</View>;

  let content: React.ReactNode;
  if (screen === 'moods') content = <>
    {header('How do you want to feel?', 'Choose one to see a walk that fits.', () => setScreen('home'))}
    <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>
      {moods.map(m => <Pressable key={m.label} onPress={() => { setMood(m.label); setScreen('preferences'); }} style={s.moodOption} accessibilityRole="button" accessibilityLabel={m.label}>
        <View style={[s.moodOptionIcon, { backgroundColor: m.color }]}><Ionicons name={m.icon} size={20} color={C.dark} /></View><View style={{ flex: 1 }}><Text style={s.moodOptionTitle}>{m.label}</Text></View><Ionicons name="chevron-forward" size={19} color={C.ink} />
      </Pressable>)}
    </ScrollView>
  </>;
  else if (screen === 'preferences') content = <>
    {header('How much time do you have?', 'Pick a range for this walk.', () => setScreen('moods'))}
    <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>
      <View style={s.contextCard}><View style={s.contextIcon}><Ionicons name="time-outline" size={21} color={C.dark} /></View><View style={{ flex: 1 }}><Text style={s.contextLabel}>WALKING TIME</Text><Text style={s.contextMood}>{time}</Text></View></View>
      <View style={s.choiceWrap}>{timeOptions.map(t => <Choice key={t} label={t} selected={time === t} onPress={() => setTime(t)} />)}</View>
    </ScrollView><View dataSet={{ mobile: 'screen-action' }} style={s.bottomAction}><Button label="Continue" icon="arrow-forward" onPress={() => setScreen('priorities')} /></View>
  </>;
  else if (screen === 'priorities') content = <>
    {header('What matters on this walk?', 'Choose up to two route details.', () => setScreen('preferences'))}
    <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>
      <View style={s.contextCard}><View style={s.contextIcon}><Ionicons name={moodIcon(mood)} size={21} color={C.dark} /></View><View style={{ flex: 1 }}><Text style={s.contextLabel}>YOUR WALK</Text><Text style={s.contextMood}>{mood} - {time}</Text></View></View>
      <View style={s.priorityList}>{environments.map(e => <Choice key={e} label={e} selected={environment.includes(e)} onPress={() => toggleEnvironment(e)} check />)}</View>
    </ScrollView><View dataSet={{ mobile: 'screen-action' }} style={s.bottomAction}><Button label="Show 3 route options" icon="arrow-forward" onPress={() => setScreen('results')} /></View>
  </>;
  else if (screen === 'results') content = <>
    {header('A few walks for you', `Matched to ${mood.toLowerCase()} and ${time}.`, () => setScreen('priorities'))}
    <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>{recommendations.map(r => routeCard(r))}{recommendations.length === 0 && <Empty icon="map-outline" title="No routes found" body="Try another time range or route preference." />}</ScrollView>
  </>;
  else if (screen === 'detail') content = <>
    <View style={s.detailMap}><LargeMap color={route.color} /><Pressable onPress={() => setScreen('results')} style={s.floatingBack}><Ionicons name="chevron-back" size={22} color={C.ink} /></Pressable><View style={s.mapCaption}><Ionicons name="location" size={14} color={C.dark} /><Text style={s.mapCaptionText}>Illustrative route · {route.area}</Text></View></View>
    <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.detailBody} showsVerticalScrollIndicator={false}><View style={s.detailNameRow}><View style={{ flex: 1 }}><Text style={s.detailTitle}>{route.name}</Text><Text style={s.routeArea}>{route.area}</Text></View><Pressable onPress={() => toggleSaved(route.id)} style={s.saveAction} accessibilityRole="button" accessibilityLabel={store.saved.includes(route.id) ? 'Remove saved route' : 'Save route'}><Ionicons name={store.saved.includes(route.id) ? 'bookmark' : 'bookmark-outline'} size={18} color={C.green} /><Text style={s.saveActionText}>{store.saved.includes(route.id) ? 'Saved' : 'Save'}</Text></Pressable></View>
      <View style={s.detailMetrics}><Metric icon="time-outline" label={`${route.minutes} min`} /><Metric icon="walk-outline" label={`${route.km.toFixed(1)} km`} /><Metric icon="trending-up-outline" label={route.difficulty} /></View>
      <Text style={s.detailDescription}>{route.description}</Text><View dataSet={{ mobile: 'env-grid' }} style={s.envGrid}><EnvCard label="Safety*" value={route.safety} max={5} icon="shield-checkmark-outline" /><EnvCard label="Greenery" value={route.green} max={5} icon="leaf-outline" /><EnvCard label="Crowds" value={route.crowd} max={5} icon="people-outline" /></View><Text style={s.sampleDisclosure}>SAMPLE ROUTE · Lighting: {route.lighting}</Text>
    </ScrollView><View dataSet={{ mobile: 'screen-action' }} style={s.bottomAction}><Button label="Continue to music ideas" icon="arrow-forward" onPress={() => setScreen('music')} /></View>
  </>;
  else if (screen === 'music') content = <>
    {header('Music for this walk', `Optional listening ideas for ${mood.toLowerCase()}.`, () => setScreen('detail'))}
    <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>
      <View style={s.musicIntro}><View style={s.musicIntroIcon}><Ionicons name="headset-outline" size={23} color={C.dark} /></View><Text style={s.musicIntroTitle}>{route.name}</Text><Text style={s.sampleDisclosure}>LISTENING IDEAS · NO AUDIO PLAYS</Text></View>
      {musicIdeas[mood].map((idea, index) => <Pressable key={idea} onPress={() => setSelectedMusic(idea)} style={[s.musicChoice, selectedMusic === idea && s.musicChoiceSelected]} accessibilityRole="radio" accessibilityState={{ selected: selectedMusic === idea }} accessibilityLabel={`${idea}${selectedMusic === idea ? ', selected' : ''}`}>
        <View style={[s.musicChoiceIcon, index === 1 && s.musicChoiceIconWarm]}><Ionicons name={index === 0 ? 'musical-notes-outline' : index === 1 ? 'cloud-outline' : 'leaf-outline'} size={20} color={C.dark} /></View><View style={{ flex: 1 }}><Text style={s.musicChoiceTitle}>{idea}</Text></View><Ionicons name={selectedMusic === idea ? 'checkmark-circle' : 'ellipse-outline'} size={21} color={selectedMusic === idea ? C.green : '#A8B0A9'} />
      </Pressable>)}
    </ScrollView><View dataSet={{ mobile: 'screen-action' }} style={s.bottomAction}><Button label="Start this walk" icon="walk" onPress={startWalk} /></View>
  </>;
  else if (screen === 'walking') content = <>
    <View dataSet={{ mobile: 'walk-top' }} style={s.walkTop}><View style={{ width: 42 }} /><Text style={s.walkModeLabel}>YOUR WALK</Text><View style={{ width: 42 }} /></View>
    <View dataSet={{ mobile: 'walk-map' }} style={s.walkMap}><LargeMap color={route.color} active /><View style={s.nextTurn}><View style={s.turnIcon}><Ionicons name="arrow-forward" size={21} color={C.white} /></View><View><Text style={s.turnKicker}>NEXT</Text><Text style={s.turnTitle}>Continue along the garden path</Text></View></View></View>
    <View dataSet={{ mobile: 'walk-stats' }} style={s.walkStats}><Text dataSet={{ mobile: 'walk-route' }} style={s.walkRoute}>{route.name}</Text><Text dataSet={{ mobile: 'walk-disclosure' }} style={s.sampleDisclosure}>DEMO WALK · PROGRESS IS AN ESTIMATE</Text><View dataSet={{ mobile: 'walk-numbers' }} style={s.walkNumbers}><View><Text style={s.walkNumber}>{route.km.toFixed(1)}</Text><Text style={s.walkUnit}>km total</Text></View><View style={s.statDivider} /><View><Text style={s.walkNumber}>{Math.max(0, route.minutes - Math.floor(elapsed / 60))}</Text><Text style={s.walkUnit}>min left</Text></View><View style={s.statDivider} /><View><Text style={s.walkNumber}>{String(Math.floor(elapsed / 60)).padStart(2, '0')}:{String(elapsed % 60).padStart(2, '0')}</Text><Text style={s.walkUnit}>elapsed</Text></View></View><View style={s.progressTrack}><View style={[s.progressFill, { width: `${Math.min(95, 8 + Math.floor(elapsed / 20))}%` }]} /></View>
      <View dataSet={{ mobile: 'walk-awareness' }} style={s.awareness}><Ionicons name="eye-outline" size={18} color={C.dark} /><Text style={s.awarenessText}>Keep your eyes on your surroundings, not your screen.</Text></View><View dataSet={{ mobile: 'walk-actions' }} style={s.walkActions}><Pressable onPress={() => setPaused(p => !p)} style={s.pauseButton}><Ionicons name={paused ? 'play' : 'pause'} size={20} color={C.dark} /><Text style={s.pauseText}>{paused ? 'Resume' : 'Pause'}</Text></Pressable><Button label="Finish walk" icon="checkmark" onPress={finishWalk} small /></View>
    </View>
  </>;
  else if (screen === 'complete') content = <View dataSet={{ mobile: 'complete-screen' }} style={s.completeScreen}><View style={s.completeArt}><ScenicArt compact /><View style={s.confetti}><Ionicons name="sparkles" size={24} color={C.orange} /></View></View><Text style={s.eyebrow}>A MOMENT WELL SPENT</Text><Text style={s.completeTitle}>Nice work.{ '\n' }You showed up for you.</Text><Text style={s.body}>A short walk is still a real step toward feeling a little better.</Text><View style={s.completionStats}><Metric icon="walk-outline" label={`${route.km.toFixed(1)} km`} /><Metric icon="time-outline" label={`${Math.max(1, Math.round(elapsed / 60) || route.minutes)} min`} /><Metric icon={moodIcon(mood)} label={mood} /></View><Button label="Quick feeling check-in" icon="chatbubble-ellipses-outline" onPress={() => setScreen('feedback')} /><Pressable style={s.textButton} onPress={() => { setScreen('home'); setTab('Discover'); }}><Text style={s.textButtonLabel}>Skip for now</Text></Pressable></View>;
  else if (screen === 'feedback') content = <>
    {header('How did that walk feel?', 'One quick tap helps tune future suggestions.', () => setScreen('complete'))}
    <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>
      <View style={s.feedbackRoute}><View style={s.feedbackThumb}><MiniMap color={route.color} /></View><View style={{ flex: 1 }}><Text style={s.feedbackRouteName}>{route.name}</Text><Text style={s.routeArea}>{route.area}</Text></View></View>
      <View style={s.feedbackOptions}>{['Much better', 'A little better', 'About the same', 'More stressed', 'More tired'].map(x => <Pressable key={x} onPress={() => submitFeedback(x)} style={s.feelingChoice} accessibilityRole="button"><Text style={s.feelingChoiceText}>{x}</Text><Ionicons name="chevron-forward" size={17} color={C.green} /></Pressable>)}</View>
    </ScrollView><View dataSet={{ mobile: 'screen-action' }} style={s.bottomAction}><Pressable onPress={() => { setScreen('home'); setTab('Discover'); }} style={s.skipButton}><Text style={s.skipLabel}>Skip this time</Text></Pressable></View>
  </>;
  else if (tab === 'Explore') {
    const filtered = routeData.filter(r => `${r.name} ${r.area} ${r.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));
    content = <>{header('Explore nearby', 'Browse a route at your own pace.')}
      <View style={s.searchBox}><Ionicons name="search-outline" size={19} color={C.muted} /><TextInput value={query} onChangeText={setQuery} placeholder="Search routes or places" placeholderTextColor="#909A93" style={s.searchInput} /></View>
      <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>{filtered.map(r => routeCard(r, true))}{filtered.length === 0 && <Empty icon="search-outline" title="No matching routes" body="Try another place or route name." />}</ScrollView>
    </>;
  } else if (tab === 'Saved') {
    const saved = routeData.filter(r => store.saved.includes(r.id));
    content = <>{header('Saved for later', saved.length ? `${saved.length} route${saved.length === 1 ? '' : 's'} you can come back to.` : 'Keep a route close for another day.')}
      <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}>{saved.map(r => routeCard(r, true))}{!saved.length && <Empty icon="bookmark-outline" title="Your saved routes live here" body="Tap the bookmark on any route to keep it handy." />}</ScrollView>
    </>;
  } else if (tab === 'Profile') {
    const totalKm = store.walks.reduce((sum, w) => sum + w.km, 0); const totalMin = store.walks.reduce((sum, w) => sum + w.minutes, 0);
    content = <>{header('Your walking space', 'A gentle record of the time you made for yourself.')}
      <ScrollView dataSet={{ mobile: 'screen-scroll' }} contentContainerStyle={s.scrollContent} showsVerticalScrollIndicator={false}><View style={s.profileCard}><View style={s.avatar}><Ionicons name="person" size={28} color={C.dark} /></View><View style={{ flex: 1 }}><Text style={s.profileName}>A little more outside</Text></View><Ionicons name="leaf-outline" size={24} color={C.green} /></View>
        <View style={s.statsCard}><View style={s.profileStat}><Text style={s.profileStatNum}>{store.walks.length}</Text><Text style={s.profileStatLabel}>walks</Text></View><View style={s.statDivider} /><View style={s.profileStat}><Text style={s.profileStatNum}>{totalKm.toFixed(1)}</Text><Text style={s.profileStatLabel}>kilometers</Text></View><View style={s.statDivider} /><View style={s.profileStat}><Text style={s.profileStatNum}>{totalMin}</Text><Text style={s.profileStatLabel}>minutes</Text></View></View>
        <View style={s.profileSectionHeader}><Text style={s.sectionTitle}>Recent walks</Text></View>
        {store.walks.slice(0, 5).map((w, i) => { const r = routeData.find(x => x.id === w.routeId); return <View style={s.historyRow} key={`${w.date}-${i}`}><View style={[s.historyIcon, { backgroundColor: r?.color ?? C.sage }]}><Ionicons name="walk-outline" size={19} color={C.dark} /></View><View style={{ flex: 1 }}><Text style={s.historyName}>{r?.name ?? 'A walk'}</Text><Text style={s.routeArea}>{new Date(w.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })} · {w.mood}</Text></View><Text style={s.historyKm}>{w.km.toFixed(1)} km</Text></View>; })}
        {!store.walks.length && <Empty icon="footsteps-outline" title="Your first walk starts here" body="Complete a route and you’ll see it in your history." />}
        <View style={s.profileSectionHeader}><Text style={s.sectionTitle}>Quick route check-ins</Text></View>{store.reviews.slice(0, 3).map((rev, i) => <View style={s.reviewCard} key={`${rev.date}-${i}`}><Text style={s.reviewTitle}>{routeData.find(r => r.id === rev.routeId)?.name ?? "Route"}</Text><Text style={s.reviewBody}>{rev.feeling} - {rev.mood}</Text></View>)}
        <Pressable style={s.locationButton} onPress={findLocation}><Ionicons name="location-outline" size={20} color={C.dark} /><View style={{ flex: 1 }}><Text style={s.locationTitle}>Location</Text><Text style={s.routeArea}>{locationLabel} · optional</Text></View><Ionicons name="chevron-forward" size={18} color={C.muted} /></Pressable>
        
      </ScrollView>
    </>;
  } else {
    content = <>
      <View style={s.homeHeader}><View style={s.brand}><View style={[s.logoMark, s.logoSmall]}><Ionicons name="leaf" size={17} color={C.white} /></View><Text style={s.brandText}>moodwalk</Text></View></View>
      <View dataSet={{ mobile: 'discover-start' }} style={s.discoverStart}>
        <View dataSet={{ mobile: 'discover-illustration' }} style={s.discoverIllustration}><ScenicArt compact /><View style={s.discoverSpark}><Ionicons name="sparkles" size={22} color={C.dark} /></View><View style={s.discoverMoodOrb}><Ionicons name="heart" size={23} color={C.dark} /></View></View>
        <Text style={s.discoverEyebrow}>A WALK THAT MEETS YOU HERE</Text>
        <Text dataSet={{ mobile: 'discover-title' }} style={s.discoverTitle}>What is your mood asking for today?</Text>
        <Button label="Choose a mood" icon="arrow-forward" onPress={() => setScreen('moods')} />
      </View>
    </>;
  }

  return <SafeAreaView dataSet={{ mobile: 'app-safe-area' }} style={s.safe}><View dataSet={{ mobile: 'app-shell', screen: screen === 'walking' ? 'walking' : 'normal' }} style={s.appShell}>
    <View dataSet={{ mobile: 'app-screen' }} style={{ flex: 1, minHeight: 0 }}>{content}</View>
    {['walking', 'complete', 'feedback', 'detail', 'music', 'moods', 'preferences', 'priorities', 'results'].includes(screen) ? null : <View dataSet={{ mobile: 'mobile-tabbar-wrap' }}>{nav}</View>}
  </View></SafeAreaView>;
}

function Button({ label, icon, onPress, small = false }: { label: string; icon: IconName; onPress: () => void; small?: boolean }) {
  return <Pressable onPress={onPress} style={[s.button, small && s.buttonSmall]} accessibilityRole="button"><Text style={[s.buttonText, small && s.buttonTextSmall]}>{label}</Text><Ionicons name={icon} size={small ? 18 : 20} color={C.white} /></Pressable>;
}
function Metric({ icon, label }: { icon: IconName; label: string }) { return <View style={s.metric}><Ionicons name={icon} size={16} color={C.green} /><Text style={s.metricText}>{label}</Text></View>; }
function Tag({ label }: { label: string }) { return <View style={s.tag}><Text style={s.tagText}>{label}</Text></View>; }
function Choice({ label, selected, onPress, check = false }: { label: string; selected: boolean; onPress: () => void; check?: boolean }) {
  const role = check ? 'checkbox' : 'radio';
  const indicator = check ? (selected ? 'checkmark-circle' : 'ellipse-outline') : (selected ? 'radio-button-on' : 'radio-button-off');
  return <Pressable onPress={onPress} style={[s.choice, selected && s.choiceSelected]} accessibilityRole={role} accessibilityState={check ? { checked: selected } : { selected }}>
    <Text style={[s.choiceText, selected && s.choiceTextSelected]}>{label}</Text><Ionicons name={indicator} size={20} color={selected ? C.green : '#A8B0A9'} />
  </Pressable>;
}
function Empty({ icon, title, body }: { icon: IconName; title: string; body: string }) { return <View style={s.empty}><View style={s.emptyIcon}><Ionicons name={icon} size={25} color={C.green} /></View><Text style={s.emptyTitle}>{title}</Text><Text style={s.emptyBody}>{body}</Text></View>; }
function EnvCard({ label, value, max, icon }: { label: string; value: number; max: number; icon: IconName }) { return <View style={s.envCard}><Ionicons name={icon} size={17} color={C.green} /><Text style={s.envLabel}>{label}</Text><Text style={s.envNumber}>{value} of {max}</Text><View style={s.envDots}>{Array.from({ length: max }).map((_, i) => <View key={i} style={[s.envDot, i < value && s.envDotOn]} />)}</View></View>; }
function RatingScale({ label, left, right, value, onChange }: { label: string; left: string; right: string; value: number; onChange: (n: number) => void }) { return <View style={s.ratingRow}><View style={s.ratingHead}><Text style={s.ratingLabel}>{label}</Text><Text style={s.ratingEndpoints}>{left} · {right}</Text></View><View style={s.ratingButtons}>{[1, 2, 3, 4, 5].map(n => <Pressable key={n} onPress={() => onChange(n)} style={[s.ratingButton, n === value && s.ratingSelected]} accessibilityRole="radio" accessibilityState={{ selected: n === value }} accessibilityLabel={`${label}: ${n} out of 5`}><Text style={[s.ratingNumber, n === value && s.ratingNumberSelected]}>{n}</Text></Pressable>)}</View></View>; }
function ScenicArt({ compact = false }: { compact?: boolean }) { return <View style={[s.scenicArt, compact && s.scenicArtCompact]}><View style={[s.sun, compact && s.sunSmall]} /><View style={s.artHillBack} /><View style={s.artHillFront} /><View style={s.artPath} /><View style={s.artTreeOne}><View style={s.treeTop} /><View style={s.treeTrunk} /></View><View style={s.artTreeTwo}><View style={s.treeTop2} /><View style={s.treeTrunk} /></View><View style={s.artCloud}><View style={s.cloudA} /><View style={s.cloudB} /></View></View>; }
function MiniMap({ color }: { color: string }) { return <View style={[s.miniMap, { backgroundColor: color }]}><Svg width="100%" height="100%" viewBox="0 0 360 150" preserveAspectRatio="xMidYMid slice"><Path d="M0 45 Q55 25 110 50 T220 40 T360 42" stroke="#F4F3E9" strokeWidth="22" fill="none" /><Path d="M40 150 Q105 115 133 90 T230 75 T325 0" stroke="#F5F4EB" strokeWidth="18" fill="none" /><Path d="M50 150 Q112 112 143 88 T236 76 T330 0" stroke="#7BA487" strokeWidth="4" strokeDasharray="5 8" fill="none" /><Circle cx="50" cy="150" r="7" fill="#527A61" stroke="white" strokeWidth="4" /><Circle cx="330" cy="0" r="7" fill="#E8A66A" stroke="white" strokeWidth="4" /><Circle cx="272" cy="35" r="13" fill="#FFFFFF" opacity=".38" /><Circle cx="96" cy="72" r="16" fill="#FFFFFF" opacity=".30" /></Svg></View>; }
function LargeMap({ color, active = false }: { color: string; active?: boolean }) { return <View style={[s.largeMap, { backgroundColor: color }]}><Svg width="100%" height="100%" viewBox="0 0 420 520" preserveAspectRatio="xMidYMid slice"><Rect width="420" height="520" fill={color} /><Path d="M-30 90 Q95 45 182 92 T440 64" stroke="#F5F2E6" strokeWidth="38" fill="none" /><Path d="M30 550 Q84 435 136 340 T196 210 T302 -30" stroke="#E6E7D8" strokeWidth="31" fill="none" /><Path d="M-20 290 Q85 260 185 285 T440 255" stroke="#F4F0E3" strokeWidth="24" fill="none" /><Path d="M55 520 Q108 435 157 355 T209 223 T307 40" stroke="#F7F8F4" strokeWidth="20" fill="none" /><Path d="M55 520 Q108 435 157 355 T209 223 T307 40" stroke="#527A61" strokeWidth="5" strokeDasharray="3 0" fill="none" /><Path d="M-10 90 Q90 55 180 92 T430 65" stroke="#D4D8CB" strokeWidth="2" fill="none" /><Circle cx="55" cy="520" r="12" fill="#527A61" stroke="white" strokeWidth="5" /><Circle cx="307" cy="40" r="12" fill="#E8A66A" stroke="white" strokeWidth="5" /><Circle cx="340" cy="360" r="28" fill="#FFFFFF" opacity=".35" /><Circle cx="80" cy="210" r="36" fill="#FFFFFF" opacity=".25" />{active && <Circle cx="187" cy="305" r="12" fill="#E8A66A" stroke="white" strokeWidth="6" />}</Svg><View style={s.mapNorth}><Ionicons name="navigate" size={15} color={C.dark} /></View></View>; }

